entries.syntax:
// E.4, Pseudocode E.1
aligned(8) class AC4SampleEntry extends AudioSampleEntry('ac-4') {
 AC4SpecificBox();
 // we permit any number of AC4PresentationLabel boxes:
 AC4PresentationLabelBox() [];
 Box () [];
}

// E.5, Pseudocode E.2: an ac4_dsi_v1() (E.6.1), to the end of the box
aligned(8) class AC4SpecificBox extends Box('dac4') {
 bit(3) ac4_dsi_version;
 bit(7) bitstream_version;
 bit(1) fs_index;
 bit(4) frame_rate_index;
 bit(9) n_presentations;
 if (bitstream_version > 1) {
  bit(1) b_program_id;
  if (b_program_id) {
   bit(16) short_program_id;
   bit(1) b_uuid;
   if (b_uuid) {
    bit(8) program_uuid[16];
   }
  }
 }
 AC4BitrateDsi ac4_bitrate_dsi;
 byte_alignment(); // byte_align, 0..7: to a byte from the start of ac4_dsi_v1
 AC4PresentationDsi presentations[n_presentations];
}
// E.7.1
aligned(8) class AC4BitrateDsi() {
 bit(2) bit_rate_mode;
 bit(32) bit_rate;
 bit(32) bit_rate_precision;
}
// a presentation of ac4_dsi_v1(): its version, and its pres_bytes (pres_bytes += add_pres_bytes). Version 1's content
// is ac4_presentation_v1_dsi() (E.10); version 0's (ETSI TS 103 190-1, not at hand) and any other's are bytes
aligned(8) class AC4PresentationDsi() {
 bit(8) presentation_version;
 bit(8) pres_bytes;
 if (pres_bytes == 255) {
  bit(16) add_pres_bytes;
 }
 if (presentation_version == 1) {
  AC4PresentationV1Dsi(pres_bytes + add_pres_bytes) presentation_v1;
 }
 else {
  bit(8) presentation_data[pres_bytes + add_pres_bytes];
 }
}
// E.10.1: in [a, b] written out, the loops over sg counted by i, b_add_emdf_substreams = 1 of config 0x06 in the condition; the spec's dsi_presentation_channel_mode is its dsi_presentation_ch_mode.
// skip_area: what is left of pres_bytes (E.6.1), which the presentation ends with
aligned(8) class AC4PresentationV1Dsi(pres_bytes) {
 bit(5) presentation_config_v1;
 if (presentation_config_v1 != 0x06) {
  bit(3) md_compat;
  bit(1) b_presentation_id;
  if (b_presentation_id) {
   bit(5) presentation_id;
  }
  bit(2) dsi_frame_rate_multiply_info;
  bit(2) dsi_frame_rate_fraction_info;
  bit(5) presentation_emdf_version;
  bit(10) presentation_key_id;
  bit(1) b_presentation_channel_coded;
  if (b_presentation_channel_coded) {
   bit(5) dsi_presentation_ch_mode;
   if (dsi_presentation_ch_mode >= 11 && dsi_presentation_ch_mode <= 14) {
    bit(1) pres_b_4_back_channels_present;
    bit(2) pres_top_channel_pairs;
   }
   bit(6) reserved_zero;
   bit(18) presentation_v1_channel_groups;
  }
  bit(1) b_presentation_core_differs;
  if (b_presentation_core_differs) {
   bit(1) b_presentation_core_channel_coded;
   if (b_presentation_core_channel_coded) {
    bit(2) dsi_presentation_channel_mode_core;
   }
  }
  bit(1) b_presentation_filter;
  if (b_presentation_filter) {
   bit(1) b_enable_presentation;
   bit(8) n_filter_bytes;
   bit(8) filter_data[n_filter_bytes];
  }
  if (presentation_config_v1 == 0x1f) {
   AC4SubstreamGroupDsi substream_group;
  }
  else {
   bit(1) b_multi_pid;
   if (presentation_config_v1 <= 2) {
    for (i = 0; i < 2; i++) {
     AC4SubstreamGroupDsi substream_groups;
    }
   }
   if (presentation_config_v1 == 3 || presentation_config_v1 == 4) {
    for (i = 0; i < 3; i++) {
     AC4SubstreamGroupDsi substream_groups;
    }
   }
   if (presentation_config_v1 == 5) {
    bit(3) n_substream_groups_minus2;
    for (i = 0; i < n_substream_groups_minus2 + 2; i++) {
     AC4SubstreamGroupDsi substream_groups;
    }
   }
   if (presentation_config_v1 > 5) {
    bit(7) n_skip_bytes;
    bit(8) skip_data[n_skip_bytes];
   }
  }
  bit(1) b_pre_virtualized;
  bit(1) b_add_emdf_substreams;
 }
 if (presentation_config_v1 == 0x06 || b_add_emdf_substreams) {
  bit(7) n_add_emdf_substreams;
  for (j = 0; j < n_add_emdf_substreams; j++) {
   bit(5) substream_emdf_version;
   bit(10) substream_key_id;
  }
 }
 bit(1) b_presentation_bitrate_info;
 if (b_presentation_bitrate_info) {
  AC4BitrateDsi ac4_bitrate_dsi;
 }
 bit(1) b_alternative;
 if (b_alternative) {
  byte_alignment();
  AC4AlternativeInfo alternative_info;
 }
 byte_alignment();
 if (bits_read() <= (pres_bytes - 1) * 8) {
  bit(1) de_indicator;
  bit(1) immersive_audio_indicator;
  bit(4) reserved;
  bit(1) b_extended_presentation_id;
  if (b_extended_presentation_id) {
   bit(9) extended_presentation_id;
  }
  else {
   bit(1) reserved1;
  }
 }
 bit(8) skip_area[pres_bytes - bits_read() / 8];
}
// E.11.1
aligned(8) class AC4SubstreamGroupDsi() {
 bit(1) b_substreams_present;
 bit(1) b_hsf_ext;
 bit(1) b_channel_coded;
 bit(8) n_substreams;
 for (i = 0; i < n_substreams; i++) {
  bit(2) dsi_sf_multiplier;
  bit(1) b_substream_bitrate_indicator;
  if (b_substream_bitrate_indicator) {
   bit(5) substream_bitrate_indicator;
  }
  if (b_channel_coded) {
   bit(6) reserved_zero;
   bit(18) dsi_substream_channel_groups;
  }
  else {
   bit(1) b_ajoc;
   if (b_ajoc) {
    bit(1) b_static_dmx;
    if (!b_static_dmx) {
     bit(4) n_dmx_objects_minus1;
    }
    bit(6) n_umx_objects_minus1;
   }
   bit(1) b_substream_contains_bed_objects;
   bit(1) b_substream_contains_dynamic_objects;
   bit(1) b_substream_contains_ISF_objects;
   bit(1) reserved;
  }
 }
 bit(1) b_content_type;
 if (b_content_type) {
  bit(3) content_classifier;
  bit(1) b_language_indicator;
  if (b_language_indicator) {
   bit(6) n_language_tag_bytes;
   bit(8) language_tag_bytes[n_language_tag_bytes];
  }
 }
}
// E.12.1, the loop over t counted by i
aligned(8) class AC4AlternativeInfo() {
 bit(16) name_len;
 bit(8) presentation_name[name_len];
 bit(5) n_targets;
 for (i = 0; i < n_targets; i++) {
  bit(3) target_md_compat;
  bit(8) target_device_category;
 }
}

// E.5a, Pseudocode E.2a
aligned(8) class AC4PresentationLabelBox extends FullBox('lac4', version = 0, 0) {
 unsigned int(16) num_presentation_labels;
 utf8string language_tag;
 for (i=0; i < num_presentation_labels; i++) {
  unsigned int(16) presentation_id;
  utf8string presentation_label;
 }
}
